/**
 * Rasterizes the Glint Research logo SVG (from ../embedme.html) into a braille
 * pixel grid baked into src/generated/logo.ts. Run via `bun run scripts/build-logo.ts`.
 * Requires ImageMagick (`convert`).
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const ROOT = join(import.meta.dir, "..");
const W = 112;
const H = 112;

const html = readFileSync(join(ROOT, "..", "embedme.html"), "utf8");
const svgMatch = html.match(/<svg[\s\S]*?<\/svg>/);
if (!svgMatch) throw new Error("no <svg> found in embedme.html");

// Drop the white full-canvas background path so only logo ink rasterizes.
const svg = svgMatch[0].replace(/<path fill="#FAFAF9" d="M0 0L2000 0L2000 2000L0 2000L0 0Z"\/>/, "");

const svgPath = "/tmp/glint-logo.svg";
writeFileSync(svgPath, svg);

const proc = Bun.spawnSync(
  [
    "convert",
    "-background", "white",
    svgPath,
    "-resize", `${W}x${H}`,
    "-colorspace", "Gray",
    "-depth", "8",
    "pgm:-",
  ],
  { stdout: "pipe", stderr: "pipe" },
);
if (proc.exitCode !== 0) {
  throw new Error(`convert failed: ${proc.stderr.toString()}`);
}

const pgm = new Uint8Array(proc.stdout);
const { width, height, pixels } = parsePgm(pgm);

const cols = Math.ceil(width / 2);
const rows = Math.ceil(height / 4);
const DOT_BITS = [
  [0x01, 0x08],
  [0x02, 0x10],
  [0x04, 0x20],
  [0x40, 0x80],
];

const grid: string[] = [];
for (let cy = 0; cy < rows; cy++) {
  let row = "";
  for (let cx = 0; cx < cols; cx++) {
    let bits = 0;
    for (let dy = 0; dy < 4; dy++) {
      for (let dx = 0; dx < 2; dx++) {
        const px = cx * 2 + dx;
        const py = cy * 4 + dy;
        if (px >= width || py >= height) continue;
        const v = pixels[py * width + px];
        if (v < 128) bits |= DOT_BITS[dy][dx];
      }
    }
    row += bits === 0 ? " " : String.fromCharCode(0x2800 + bits);
  }
  grid.push(row.trimEnd());
}

while (grid.length > 0 && grid[0].trim() === "") grid.shift();
while (grid.length > 0 && grid[grid.length - 1].trim() === "") grid.pop();

const out = `// Generated by scripts/build-logo.ts — do not edit by hand.
export const LOGO_ROWS: string[] = ${JSON.stringify(grid, null, 2)};
export const LOGO_WIDTH = ${Math.max(...grid.map((r) => r.length))};
`;
writeFileSync(join(ROOT, "src", "generated", "logo.ts"), out);
console.log(`logo: ${grid.length} rows x ${Math.max(...grid.map((r) => r.length))} cols`);
console.log(grid.join("\n"));

function parsePgm(data: Uint8Array): { width: number; height: number; pixels: Uint8Array } {
  let pos = 0;
  const token = (): string => {
    while (pos < data.length && /\s/.test(String.fromCharCode(data[pos]))) pos++;
    if (String.fromCharCode(data[pos]) === "#") {
      while (pos < data.length && data[pos] !== 10) pos++;
      return token();
    }
    let t = "";
    while (pos < data.length && !/\s/.test(String.fromCharCode(data[pos]))) {
      t += String.fromCharCode(data[pos]);
      pos++;
    }
    return t;
  };
  const magic = token();
  if (magic !== "P5") throw new Error(`expected P5 pgm, got ${magic}`);
  const width = Number(token());
  const height = Number(token());
  token();
  pos++;
  return { width, height, pixels: data.slice(pos, pos + width * height) };
}
